#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Manual end-to-end test of proz before a release. Stages 1 to 12 run in a
# throwaway sandbox (its own XDG_CONFIG_HOME and CLAUDE_CONFIG_DIR), so the
# real ~/.config/proz is never read or written. Only stage 13 touches the
# real install, and it asks first and backs it up.

REPO=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
SB="${PROZ_TEST_DIR:-$HOME/.cache/proz-manual-test}"
BIN="$SB/bin"
P="$BIN/proz"
DB="$SB/config/proz/proz.db"
ENV_FILE="$SB/wizard.env"
PASSED=(); FAILED=()

ok()  { PASSED+=("$1"); printf '  %s✓ %s%s\n' "$GREEN" "$1" "$RESET"; }
bad() { FAILED+=("$1"); warn "FAIL: $1"; }

# show CMD... runs a command visibly and never aborts the wizard.
show() {
  printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET"
  "$@" 2>&1 | sed 's/^/    /' || true
}

# expect LABEL NEEDLE CMD... passes when the output contains NEEDLE.
expect() {
  local label=$1 needle=$2 out; shift 2
  printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET"
  out=$("$@" 2>&1) || true
  printf '%s\n' "$out" | sed 's/^/    /'
  if grep -qF -- "$needle" <<<"$out"; then ok "$label"; else bad "$label (wanted: $needle)"; fi
}

# expect_not LABEL NEEDLE CMD... passes when the output lacks NEEDLE.
expect_not() {
  local label=$1 needle=$2 out; shift 2
  printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET"
  local rc=0
  out=$("$@" 2>&1) || rc=$?
  printf '%s\n' "$out" | sed 's/^/    /'
  if (( rc != 0 )) || [[ -z "$out" ]]; then bad "$label (command failed or printed nothing)"
  elif grep -qF -- "$needle" <<<"$out"; then bad "$label (found: $needle)"; else ok "$label"; fi
}

# human QUESTION records what only a person can see (a popup, an icon).
human() { if confirm "$1"; then ok "$1"; else bad "$1"; fi; }

# sql runs one statement on the sandbox database: the test's time machine.
sql() { python3 -c 'import sqlite3,sys; c=sqlite3.connect(sys.argv[1]); c.execute(sys.argv[2]); c.commit()' "$DB" "$1"; }

# count QUERY prints the first column of the first row.
count() { python3 -c 'import sqlite3,sys; print(sqlite3.connect(sys.argv[1]).execute(sys.argv[2]).fetchone()[0])' "$DB" "$1"; }

days_ago() { date -d "$1 days ago" '+%Y-%m-%d %H:%M:%S'; }

# claude_session DIR DAYS PROMPT fakes one Claude Code session in DIR.
claude_session() {
  python3 - "$CLAUDE_CONFIG_DIR" "$1" "$2" "$3" <<'PY'
import json, os, re, sys, time, datetime
config, cwd, days, text = sys.argv[1], sys.argv[2], int(sys.argv[3]), sys.argv[4]
at = time.time() - days * 86400
d = os.path.join(config, "projects", re.sub(r"[^A-Za-z0-9]", "-", cwd))
os.makedirs(d, exist_ok=True)
ts = datetime.datetime.fromtimestamp(at, datetime.timezone.utc).isoformat().replace("+00:00", "Z")
rec = {"type": "user", "cwd": cwd, "timestamp": ts, "message": {"role": "user", "content": text}}
path = os.path.join(d, "s1.jsonl")
open(path, "w").write(json.dumps(rec) + "\n")
os.utime(path, (at, at))
PY
}

# mcp sends one tools/call to 'proz mcp' over stdio and prints the reply.
mcp() {
  { printf '%s\n' \
      '{"jsonrpc":"2.0","id":1,"method":"initialize","params":{"protocolVersion":"2025-06-18","capabilities":{},"clientInfo":{"name":"wizard","version":"1"}}}' \
      '{"jsonrpc":"2.0","method":"notifications/initialized"}' \
      "{\"jsonrpc\":\"2.0\",\"id\":2,\"method\":\"$1\",\"params\":$2}"
    sleep 1; } | "$P" mcp | tail -n1
}

# open_bg opens a file or URL without waiting: on sway xdg-open can block
# until the app closes.
open_bg() { open_url "$1" & disown; sleep 1; }

results() {
  _clear
  local report="$SB/report.txt"
  { echo "proz manual test, $(date '+%Y-%m-%d %H:%M'), $(git -C "$REPO" rev-parse --short HEAD)"
    echo "passed: ${#PASSED[@]}  failed: ${#FAILED[@]}"
    for f in "${FAILED[@]}"; do echo "FAIL: $f"; done
    for p in "${PASSED[@]}"; do echo "ok:   $p"; done; } > "$report"
  printf '\n%s  Results: %s passed, %s failed%s\n' "$BOLD" "${#PASSED[@]}" "${#FAILED[@]}" "$RESET"
  for f in "${FAILED[@]}"; do warn "$f"; done
  note "Full report: $report (paste it to Claude to triage the failures)."
  note "Clean up the sandbox: rm -rf $SB"
  pause "Press Enter to finish"
}

run_wizard() {

# The sandbox relies on XDG_CONFIG_HOME, which proz ignores on macOS, and the
# stages use GNU date and touch.
[[ "$(uname -s)" == Linux ]] || { warn "This test runs on Linux only."; exit 1; }
# Stage 1 deletes folders inside the sandbox, so it must be a folder of its own.
case "$SB" in "" | / | "$HOME" | "$HOME/") warn "PROZ_TEST_DIR must be a folder of its own, not $SB"; exit 1 ;; esac

TOTAL_STAGES=13

banner "proz manual test"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Prerequisites and build"
say "Builds proz twice into the sandbox: plain, and with the tray."
note "Sandbox: $SB"
for tool in go git python3 notify-send; do
  if command -v "$tool" >/dev/null 2>&1; then ok "$tool installed"; else bad "$tool installed"; fi
done
if [[ -d "$SB/config" ]] && confirm "A sandbox from an earlier run exists. Wipe it and start fresh?"; then
  rm -rf "$SB/config" "$SB/claude" "$SB/projects" "$SB/brain"
fi
mkdir -p "$BIN" "$SB/config/proz" "$SB/claude" "$SB/projects" "$SB/brain"
export XDG_CONFIG_HOME="$SB/config" CLAUDE_CONFIG_DIR="$SB/claude"
# go must keep using the real module cache and toolchain, not the sandbox
export GOMODCACHE="${GOMODCACHE:-$(go env GOMODCACHE)}" GOCACHE="${GOCACHE:-$(go env GOCACHE)}"
(cd "$REPO" && go build -o "$P" . && go build -tags tray -o "$BIN/proz-tray" .) && ok "both binaries build" || bad "both binaries build"
show "$P" --help
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Import from an old store.json"
say "An install from before SQLite kept projects in store.json. The first"
say "command imports it once and leaves the file as a backup."
mkdir -p "$SB/projects/legacy-app"
touch -d "$(days_ago 12)" "$SB/projects/legacy-app"
cat > "$SB/config/proz/store.json" <<JSON
[{"name": "legacy-app", "path": "$SB/projects/legacy-app", "programs": ["ls"], "arguments": ["-la"]}]
JSON
echo '["ls"]' > "$SB/config/proz/recent.json"
expect "legacy project imported" "legacy-app" "$P" status legacy-app --json
[[ -f "$SB/config/proz/store.json" ]] && ok "store.json left as a backup" || bad "store.json left as a backup"
"$P" nudges >/dev/null 2>&1 || true
[[ $(count "SELECT count(*) FROM projects WHERE name = 'legacy-app'") == 1 ]] && ok "import runs only once" || bad "import runs only once"
[[ $(count "SELECT programs FROM projects WHERE name = 'legacy-app'") == *ls* ]] && ok "programs carried over" || bad "programs carried over"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Projects with old activity"
say "Creates four projects and one idea, then moves their history back in"
say "time so they look quiet without waiting a week:"
step "web: a git repo, last commit 10 days ago, on main and feature/login (checked out), 2 untracked files"
step "habit tracker: plain files from 9 days ago and a Claude Code session 8 days ago"
step "fresh: a file changed just now, so it must not nudge"
step "offline sync: an idea with no folder"
W="$SB/projects/web"
mkdir -p "$W"
git -C "$W" init -q -b main
echo hi > "$W/work.txt"
GIT_AUTHOR_DATE="$(days_ago 10)" GIT_COMMITTER_DATE="$(days_ago 10)" \
  git -C "$W" -c user.name=wizard -c user.email=wizard@example.test add work.txt
GIT_AUTHOR_DATE="$(days_ago 10)" GIT_COMMITTER_DATE="$(days_ago 10)" \
  git -C "$W" -c user.name=wizard -c user.email=wizard@example.test commit -q -m "wire up the login page"
git -C "$W" checkout -q -b feature/login
echo a > "$W/notes.txt"; echo b > "$W/todo.txt"
touch -d "$(days_ago 10)" "$W/work.txt" "$W/notes.txt" "$W/todo.txt"
H="$SB/projects/habit-tracker"
mkdir -p "$H"
echo "streaks" > "$H/README.md"; touch -d "$(days_ago 9)" "$H/README.md" "$H"
claude_session "$H" 8 "wire the signup form to the api"
mkdir -p "$SB/projects/fresh"; echo now > "$SB/projects/fresh/main.go"
say "Adding web opens the program picker, a real feature worth a look:"
step "Browse it (Tab shows all PATH binaries), then press q to save without a program"
step "At the Arguments prompt, press Enter"
pause "Press Enter to open the picker"
(cd "$W" && "$P" add web) || bad "proz add web"
(cd "$H" && "$P" add "habit tracker" </dev/null) | sed 's/^/    /' || bad "proz add habit tracker"
"$P" "$SB/projects/fresh" </dev/null | sed 's/^/    /' || bad "proz <path> registers fresh"
show "$P" idea "offline sync"
sql "UPDATE projects SET created_at = created_at - 11*86400 WHERE name != 'fresh'"
ok "history moved back"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Left-off notes and nudges"
expect "web note names the checked-out branch" "Branch: feature/login" "$P" status web
expect "web note has the last commit" "Last commit: wire up the login page" "$P" status web
expect "web note counts untracked files" "Uncommitted: 2 files" "$P" status web
expect "Claude session gives the last prompt" "Last prompt: wire the signup form to the api" "$P" status "habit tracker"
expect "habit tracker quiet for 8 days" "Quiet for 8 days" "$P" status "habit tracker"
expect "idea nudges too" "offline sync" "$P" nudges
expect_not "fresh does not nudge" "fresh" "$P" nudges
expect "nudges --json has the note" '"note"' "$P" nudges --json
say "Read the notes above. A note shows only the signals a project has:"
step "web: last commit, branch and uncommitted files (git)"
step "habit tracker: your last Claude Code prompt"
step "legacy-app and offline sync: no git, milestone or session yet, so only how long they have been quiet"
human "Each note shows what its project has, and nothing looks wrong"
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Notifications"
if pgrep -x mako >/dev/null || pgrep -x dunst >/dev/null || pgrep -x swaync >/dev/null || pgrep -f notification-daemon >/dev/null; then
  ok "a notification daemon is running"
else
  warn "No mako, dunst or swaync found. On Sway, notifications need one: sudo apt install mako-notifier, then run mako."
  pause "Start one in another terminal, then press Enter"
fi
show "$P" test notification
human "A sample proz notification appeared"
say "Four projects are quiet, so one check sends one summary, not four popups."
show "$P" check
human "One summary notification about 4 quiet projects appeared"
expect_not "a second check stays silent" "habit tracker" "$P" check --json
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Snooze, drop, restore, resume"
show "$P" snooze "habit tracker" 3
expect_not "snoozed project leaves nudges" "habit tracker" "$P" nudges
show "$P" drop "offline sync"
expect "dropped idea is archived" "offline sync" "$P" archived
expect_not "dropped idea leaves nudges" "offline sync" "$P" nudges
show "$P" restore "offline sync"
expect "restored idea nudges again" "offline sync" "$P" nudges
say "Resume prints the note, then opens the project with its program (ls -la here)."
show "$P" resume legacy-app
human "The note and then a listing of the legacy-app folder were printed"
expect_not "resuming counts as activity" "legacy-app" "$P" nudges
say "Now the snooze runs out (moved into the past):"
# as if the 3 days passed: the snooze and the earlier notification move back too
sql "UPDATE projects SET snoozed_until = strftime('%s','now') - 60, snoozed_at = snoozed_at - 3*86400, notified_at = notified_at - 3*86400 WHERE name = 'habit tracker'"
expect "the ended snooze notifies again" "habit tracker" "$P" check --json
human "One notification for habit tracker alone appeared, with its note"
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Milestones"
show "$P" milestone web "shipped login; next: signup"
expect "milestone joins the note" "Milestone: shipped login; next: signup" "$P" status web
expect_not "a milestone is activity" "web" "$P" nudges
expect "milestones in --json" '"milestones"' "$P" status web --json
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Brain folder"
say "Points proz at a markdown folder (a stand-in for your Obsidian vault)."
show "$P" config brain-path "$SB/brain"
show "$P" check
show ls "$SB/brain"
[[ -f "$SB/brain/web.md" && -f "$SB/brain/habit-tracker.md" ]] && ok "one note per project" || bad "one note per project"
expect "note has the milestone" "shipped login; next: signup" cat "$SB/brain/web.md"
say "Your own text around proz's section must survive a rewrite:"
{ printf '# Web\n\nmy own notes\n\n'; cat "$SB/brain/web.md"; printf '\nmore notes below\n'; } > "$SB/brain/web.tmp" && mv "$SB/brain/web.tmp" "$SB/brain/web.md"
show "$P" milestone web "second milestone"
expect "text above the section kept" "my own notes" cat "$SB/brain/web.md"
expect "text below the section kept" "more notes below" cat "$SB/brain/web.md"
expect "section refreshed by the milestone" "second milestone" cat "$SB/brain/web.md"
expect "proz brain --json" '"content"' "$P" brain web --json
open_bg "$SB/brain/web.md"
human "web.md reads well as a markdown note"
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Prompts switch"
expect "prompt in the brain note by default" "wire the signup form" cat "$SB/brain/habit-tracker.md"
show "$P" config prompts off
expect_not "prompt gone from the brain note at once" "wire the signup form" cat "$SB/brain/habit-tracker.md"
expect_not "prompt gone from status" "Last prompt" "$P" status "habit tracker"
expect "session still counts as activity" "Quiet for 8 days" "$P" status "habit tracker"
show "$P" config prompts on
expect "prompt back when switched on" "wire the signup form" cat "$SB/brain/habit-tracker.md"
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "MCP for agents"
say "Talks to 'proz mcp' over stdio like Claude Code would."
expect "tools listed" "read_brain_note" mcp tools/list "{}"
expect "list_nudges" "habit tracker" mcp tools/call '{"name":"list_nudges","arguments":{}}'
expect "get_project by name" "feature/login" mcp tools/call '{"name":"get_project","arguments":{"project":"web"}}'
expect "get_project by working directory" "feature/login" mcp tools/call "{\"name\":\"get_project\",\"arguments\":{\"dir\":\"$W\"}}"
expect "read_brain_note" "my own notes" mcp tools/call '{"name":"read_brain_note","arguments":{"project":"web"}}'
show mcp tools/call '{"name":"record_milestone","arguments":{"project":"fresh","text":"set up by an agent"}}'
expect "record_milestone" "set up by an agent" "$P" status fresh
pause

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Email digest through Mailtrap Local"
if (exec 3<>/dev/tcp/127.0.0.1/3535) 2>/dev/null; then
  ok "Mailtrap Local is listening on 3535"
else
  say "Mailtrap Local catches mail on 127.0.0.1:3535; nothing leaves your machine."
  step "Install it: sudo snap install mailtrap-local"
  step "Or download mailtrap-local_<version>_linux_amd64.tar.gz from the releases page"
  open_bg "https://github.com/mailtrap/mailtrap-local/releases"
  step "Run it in another terminal: mailtrap-local"
  pause "Press Enter once it is running"
  if (exec 3<>/dev/tcp/127.0.0.1/3535) 2>/dev/null; then ok "Mailtrap Local is listening on 3535"; else bad "Mailtrap Local is listening on 3535"; fi
fi
show "$P" config email
expect "email refused before SMTP is set" "configure SMTP first" "$P" config email on
show "$P" config smtp --host 127.0.0.1 --port 3535 --from "proz <proz@example.test>" --to "me@example.test"
expect "smtp settings shown without a password" "127.0.0.1" "$P" config smtp
expect "email switched on by the first setup" "on" "$P" config email
show "$P" test email
note "If that failed with a certificate error, Mailtrap offers STARTTLS with its own certificate: report it."
open_bg "http://127.0.0.1:3550"
note "Reload the Mailtrap page if the inbox looks empty."
human "The sample email arrived in Mailtrap"
MT_ID=$(curl -s http://127.0.0.1:3550/api/v1/messages | grep -o '"id":"[^"]*"' | head -1 | cut -d'"' -f4) || true
MT_RAW=$(curl -s "http://127.0.0.1:3550/api/v1/message/$MT_ID/raw")
if grep -q 'multipart/alternative' <<<"$MT_RAW" && grep -q 'Content-Type: text/html' <<<"$MT_RAW" && grep -q 'Content-Type: text/plain' <<<"$MT_RAW"; then
  ok "the sample email has a plain text part and an HTML part"
else
  bad "the sample email has a plain text part and an HTML part"
fi
human "In Mailtrap's HTML tab the email is one simple column: project name as a heading, commands in monospace, no images"
TODAY=$(date +%A | tr '[:upper:]' '[:lower:]')
say "Digest day set to today ($TODAY) so the weekly digest is due now:"
show "$P" config digest-day "$TODAY"
show "$P" nudges
show "$P" check
human "A digest arrived listing exactly the projects above, each with resume, snooze and drop commands"
show "$P" check
human "Still only one digest in Mailtrap after a second check"
pause

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Tray icon"
say "Starts the tray build in the background, still in the sandbox."
note "The icon shows in your bar's tray area (swaybar, waybar or eww's systray widget)."
"$BIN/proz-tray" tray > "$SB/tray.log" 2>&1 &
TRAY=$!
trap 'kill "$TRAY" 2>/dev/null' EXIT # Ctrl-C must not leave the sandbox tray running
sleep 3
kill -0 "$TRAY" 2>/dev/null && ok "tray is running" || bad "tray is running (see $SB/tray.log)"
human "A proz icon with a dot is in the bar"
step "Click it: each quiet project has Resume, Snooze and Drop; Snooze opens Tomorrow, 3 days, 1 week, 2 weeks, 1 month"
human "The menu lists the quiet projects with those three actions"
step "Pick Snooze, then 2 weeks, on habit tracker"
human "habit tracker left the menu"
say "Switching the tray off; it should quit on its own within 30 seconds."
show "$P" config tray off
for _ in $(seq 35); do kill -0 "$TRAY" 2>/dev/null || break; sleep 1; done
if kill -0 "$TRAY" 2>/dev/null; then bad "config tray off stops the tray within 30 seconds"; kill "$TRAY" 2>/dev/null || true; else ok "config tray off stops the tray within 30 seconds"; fi
human "The proz icon left the bar without a click"
show cat "$SB/tray.log"
pause

# ── 13 ────────────────────────────────────────────────────────────────────
stage "Real install and autostart"
say "The only stage that touches your real setup: it installs the tray build"
say "to ~/.local/bin/proz and starts it at login. It backs up first."
if confirm "Install for real now?"; then
  unset XDG_CONFIG_HOME CLAUDE_CONFIG_DIR
  BACKUP="$HOME/.config/proz.backup-$(date +%Y%m%d-%H%M%S)"
  if [[ -d "$HOME/.config/proz" ]]; then
    cp -a "$HOME/.config/proz" "$BACKUP" || { bad "real config backed up"; warn "No backup, so nothing was installed."; exit 1; }
    ok "real config backed up to $BACKUP"
  fi
  [[ -f "$HOME/.local/bin/proz" ]] && cp -a "$HOME/.local/bin/proz" "$SB/proz.previous" && note "old binary kept at $SB/proz.previous"
  install -m 755 "$BIN/proz-tray" "$HOME/.local/bin/proz" && ok "installed ~/.local/bin/proz"
  say "Your real projects, after the upgrade from your old version:"
  show proz nudges
  human "My real projects are all there and the notes look right"
  if [[ "${XDG_CURRENT_DESKTOP:-}" == *sway* ]]; then
    say "Sway ignores ~/.config/autostart, so the tray runs as a systemd user"
    say "service that sway starts once per login (contrib/sway in the repo)."
    sway_ready() {
      [[ -f "$HOME/.config/systemd/user/proz-tray.service" && -f "$HOME/.config/sway/proz.conf" ]] &&
        grep -qsx '[[:space:]]*include ~/.config/sway/proz.conf' "$HOME/.config/sway/config"
    }
    if sway_ready; then
      ok "sway starts the proz-tray service"
    else
      note "Install it yourself (backs up your sway config first):"
      note "  cp ~/.config/sway/config ~/.config/sway/config.bak"
      note "  mkdir -p ~/.config/systemd/user"
      note "  cp $REPO/contrib/sway/proz-tray.service ~/.config/systemd/user/"
      note "  cp $REPO/contrib/sway/proz.conf ~/.config/sway/"
      note "  printf '\\ninclude ~/.config/sway/proz.conf\\n' >> ~/.config/sway/config"
      note "  systemctl --user daemon-reload && sway -C"
      pause "Press Enter once installed"
      sway_ready && ok "sway starts the proz-tray service" || bad "sway starts the proz-tray service"
    fi
  else
    show proz tray autostart on
    show cat "$HOME/.config/autostart/proz.desktop"
  fi
  step "Log out and back in."
  human "After logging back in, the proz icon is in the bar without starting it by hand"
  [[ "${XDG_CURRENT_DESKTOP:-}" == *sway* ]] && show systemctl --user --no-pager status proz-tray.service
  note "Undo: proz tray autostart off (or remove the sway include and the service); restore $BACKUP and $SB/proz.previous"
else
  note "Skipped the real install."
fi
pause

results
finish
}

run_wizard "$@"; exit
